    "<div id='alvoEquipe' class='alvo'><b>Equipe</b><span id='otaEquipe'>—</span><span id='otaEquipeVersao'>—</span></div>"
    "<div id='alvoVisitantes' class='alvo'><b>Visitantes</b><span id='otaVisitantes'>—</span><span id='otaVisitantesVersao'>—</span></div>"
    "</div></article></div></section>"
    "<section id='resultadoConsulta' class='painel-resultado' hidden><div class='cabecalho-secao'><div><h2 id='tituloConsulta'>Resultado da consulta</h2><p id='descricaoConsulta'>—</p></div><button id='voltarGeral' class='secundario'>Voltar à visão geral</button></div>"
    "<div id='detalhesConsulta' class='grade'></div><details class='tecnico'><summary>Dados técnicos desta resposta</summary><div id='metaResposta' class='detalhe'>—</div><pre id='saida'>{}</pre></details></section></div>"
    "<aside class='controles'><div class='cabecalho-secao'><div><h2>Comandos disponíveis</h2><p>Selecione uma consulta ou uma ação confirmada.</p></div></div>"
    "<details class='grupo' open><summary><span>Sistema do mestre <small>4 consultas</small></span></summary><div class='comandos'>"
    "<button data-codigo='Q1' data-consulta='ping'><strong>Ping</strong><small>Confirma o enlace e mede o tempo de resposta</small></button>"
    "<button data-codigo='Q2' data-consulta='versao'><strong>Versão</strong><small>Firmware, nó e capacidades anunciadas</small></button>"
    "<button data-codigo='Q3' data-consulta='capacidades'><strong>Capacidades</strong><small>Recursos aceitos pelo protocolo</small></button>"
    "<button data-codigo='Q4' data-consulta='saude'><strong>Saúde</strong><small>Estado, causas, memória e erros históricos</small></button></div></details>"
    "<details class='grupo'><summary><span>Dados e comunicação <small>5 consultas</small></span></summary><div class='comandos'>"
    "<button data-codigo='Q5' data-consulta='telemetria'><strong>Telemetria no mestre</strong><small>Última amostra mantida pelo mestre</small></button>"
    "<button data-codigo='Q6' data-consulta='uart'><strong>UART da equipe</strong><small>Envios, recepções, erros e descartes</small></button>"
    "<button data-codigo='Q7' data-consulta='ota'><strong>Estado OTA</strong><small>Situação e versões de cada firmware</small></button>"
    "<button data-codigo='Q8' data-consulta='wifi'><strong>Wi-Fi do mestre</strong><small>Rádio, conexão, RSSI e rede atual</small></button>"
    "<button data-codigo='Q9' data-consulta='configuracao'><strong>Configuração operacional</strong><small>Relatórios, SD, intervalos OTA e política Wi-Fi</small></button></div></details>"
    "<details class='grupo'><summary><span>Satélites <small>4 consultas do terminal</small></span></summary><div class='comandos'>"
    "<button data-codigo='S1' data-consulta='satelite_equipe_ping'><strong>Ping da equipe</strong><small>O mestre consulta este satélite pela UART</small></button>"
    "<button data-codigo='S2' data-consulta='satelite_visitantes_ping'><strong>Ping de visitantes</strong><small>O mestre consulta o outro enlace UART</small></button>"
    "<button data-codigo='S3' data-consulta='satelite_equipe_versao'><strong>Versão da equipe</strong><small>Firmware e capacidades deste satélite</small></button>"
    "<button data-codigo='S4' data-consulta='satelite_visitantes_versao'><strong>Versão de visitantes</strong><small>Firmware e capacidades do satélite de visitantes</small></button></div></details>"
    "<div class='cabecalho-secao'><div><h2>Ações com confirmação</h2><p>As caixas com a faixa laranja alteram o estado do mestre.</p></div></div><details class='grupo' open><summary><span>Atualização e diagnóstico <small>7 ações</small></span></summary><div class='comandos'>"
    "<button class='acao' data-codigo='A1' data-acao='verificar_ota' data-pergunta='Solicitar ao mestre uma nova verificação de atualizações?'><strong>Verificar atualizações</strong><small>Abre uma sessão Wi-Fi temporária no mestre</small></button>"
    "<button class='acao acao-principal' data-codigo='A2' data-acao='autorizar_todos' data-pergunta='Atualizar primeiro os dois satélites e depois o mestre?'><strong>Atualizar todos</strong><small>Sequência segura: satélites antes do mestre</small></button>"
    "<button class='acao' data-codigo='A3' data-acao='autorizar_mestre' data-pergunta='Autorizar a instalação da atualização do mestre?'><strong>OTA somente do mestre</strong><small>Disponível quando houver firmware pendente</small></button>"
    "<button class='acao' data-codigo='A4' data-acao='autorizar_equipe' data-pergunta='Autorizar a atualização deste satélite da equipe?'><strong>OTA somente da equipe</strong><small>O mestre enviará o firmware pela UART</small></button>"
    "<button class='acao' data-codigo='A5' data-acao='autorizar_visitantes' data-pergunta='Autorizar a atualização do satélite de visitantes?'><strong>OTA somente de visitantes</strong><small>O mestre enviará o firmware pela UART</small></button>"
    "<button class='acao' data-codigo='A6' data-acao='resumo_terminal' data-pergunta='Solicitar um resumo no terminal serial do mestre?'><strong>Resumo no terminal</strong><small>Exibe os relatórios no console do mestre</small></button>"
    "<button class='acao perigo' data-codigo='A7' data-acao='cancelar_ota' data-pergunta='Cancelar todas as atualizações OTA pendentes?'><strong>Cancelar OTA</strong><small>Cancela autorizações e transferências pendentes</small></button></div></details>"
    "<details class='grupo'><summary><span>Operação e registros <small>3 ações</small></span></summary><div class='comandos'>"
    "<button class='acao' data-codigo='A8' data-acao='alternar_relatorios' data-pergunta='Alternar entre pausar e retomar os relatórios periódicos do terminal?'><strong>Pausar ou retomar relatórios</strong><small>Mesmo comando disponível no menu principal serial</small></button>"
    "<button class='acao perigo' data-codigo='A9' data-acao='zerar_percurso' data-pergunta='Zerar somente o percurso desta sessão, preservando o odômetro total?'><strong>Zerar percurso da sessão</strong><small>O odômetro acumulado será preservado</small></button>"
    "<button class='acao' data-codigo='A10' data-acao='sincronizar_google' data-pergunta='Fechar o CSV atual e solicitar o envio dos arquivos pendentes ao Google?'><strong>Enviar telemetria ao Google</strong><small>Executa a sincronização em segundo plano quando houver Wi-Fi</small></button></div></details>"
    "<details class='grupo'><summary><span>Intervalos <small>relatórios e OTA</small></span></summary><div class='formulario duas-colunas'>"
    "<div class='campo'><label for='grupoRelatorio'>Relatório do terminal</label><select id='grupoRelatorio'><option value='0'>Telemetria</option><option value='1'>UART</option><option value='2'>Sistema</option><option value='3'>OTA</option></select></div>"
    "<div class='campo'><label for='intervaloRelatorio'>Novo intervalo</label><select id='intervaloRelatorio'><option value='500'>500 ms</option><option value='1000'>1 segundo</option><option value='2000'>2 segundos</option><option value='5000'>5 segundos</option><option value='10000'>10 segundos</option><option value='30000'>30 segundos</option><option value='0'>Desativar</option></select></div>"
    "<div class='linha-botoes'><button id='aplicarIntervaloRelatorio' class='acao' data-codigo='I1'>Aplicar ao relatório</button></div>"
    "<div class='campo'><label for='intervaloOta'>Verificação OTA</label><select id='intervaloOta'><option value='5'>5 minutos</option><option value='15'>15 minutos</option><option value='30'>30 minutos</option><option value='60'>1 hora</option><option value='360'>6 horas</option><option value='1440'>24 horas</option></select></div>"
    "<div class='campo'><label for='intervaloTelemetriaOta'>Telemetria durante OTA</label><select id='intervaloTelemetriaOta'><option value='500'>500 ms</option><option value='1000'>1 segundo</option><option value='2000'>2 segundos</option><option value='5000'>5 segundos</option><option value='10000'>10 segundos</option></select></div>"
    "<div class='linha-botoes'><button id='aplicarIntervaloOta' class='acao' data-codigo='I2'>Aplicar verificação OTA</button><button id='aplicarIntervaloTelemetriaOta' class='acao' data-codigo='I3'>Aplicar telemetria OTA</button></div></div></details>"
    "<details class='grupo'><summary><span>Redes Wi-Fi do mestre <small>todas as operações</small></span></summary><div class='formulario duas-colunas'>"
    "<p id='resumoWifiConfiguracao' class='nota campo largo'>Consulte a configuração operacional para carregar as redes salvas.</p>"
    "<div class='campo largo'><label for='ssidWifi'>Nova rede (SSID)</label><input id='ssidWifi' maxlength='32' autocomplete='off' placeholder='Nome da rede'></div>"
    "<div class='campo largo'><label for='senhaWifi'>Senha da nova rede</label><input id='senhaWifi' class='segredo' type='password' minlength='8' maxlength='63' autocomplete='new-password' placeholder='8 a 63 caracteres'></div>"
    "<label class='alternador campo largo'><input id='salvarWifi' type='checkbox' checked>Salvar após testar a conexão</label>"
    "<div class='linha-botoes'><button id='conectarNovaWifi' class='acao' data-codigo='W1'>Testar nova rede</button><button id='definirPrincipalWifi' class='acao' data-codigo='W2'>Usar como principal</button></div>"
    "<div class='campo largo'><label for='redeWifiSalva'>Rede secundária salva</label><select id='redeWifiSalva'><option value=''>Nenhuma rede carregada</option></select></div>"
    "<div class='linha-botoes'><button id='conectarWifiSalva' class='acao' data-codigo='W3'>Conectar à selecionada</button><button id='excluirWifiSalva' class='acao perigo' data-codigo='W4'>Excluir selecionada</button></div>"
    "<div class='campo'><label for='wifiAutomatico'>Redes secundárias</label><select id='wifiAutomatico'><option value='1'>Conexão automática</option><option value='0'>Exigir autorização</option></select></div>"
    "<div class='campo'><label for='tentativasWifi'>Tentativas por rede</label><input id='tentativasWifi' type='number' min='1' max='10' value='3'></div>"
    "<div class='campo'><label for='tempoTentativaWifi'>Tempo por tentativa (ms)</label><input id='tempoTentativaWifi' type='number' min='2000' max='30000' step='500' value='8000'></div>"
    "<div class='campo'><label for='intervaloTentativasWifi'>Intervalo entre tentativas (ms)</label><input id='intervaloTentativasWifi' type='number' min='100' max='5000' step='50' value='750'></div>"
    "<div class='campo'><label for='limiteSessaoWifi'>Limite da sessão (ms)</label><input id='limiteSessaoWifi' type='number' min='5000' max='180000' step='1000' value='30000'></div>"
    "<div class='campo largo'><label for='permissaoWifi'>Senha de permissão administrativa</label><input id='permissaoWifi' class='segredo' type='password' maxlength='63' autocomplete='current-password' placeholder='Necessária nas alterações protegidas'></div>"
    "<div class='linha-botoes'><button id='aplicarWifiAutomatico' class='acao' data-codigo='W5'>Aplicar autorização</button><button id='aplicarPoliticaWifi' class='acao' data-codigo='W6'>Salvar política</button><button id='restaurarPrincipalWifi' class='acao perigo' data-codigo='W7'>Restaurar rede do firmware</button></div></div></details>"
    "<div id='confirmacao' class='confirmacao' hidden><strong id='pergunta'></strong><p>O comando será enviado ao mestre e a resposta deverá chegar pela UART.</p>"
    "<div class='linha-botoes'><button id='confirmar'>Confirmar envio</button><button id='voltar'>Voltar</button></div></div></aside></div>"
    "<section class='historico-bloco'><div class='cabecalho-secao'><div><h2>Histórico desta página</h2><p>Últimos comandos enviados neste navegador.</p></div></div><ul id='historico' class='historico'><li><span>—</span><span>Nenhum comando enviado</span><small>—</small></li></ul></section>"
    "</main><script>"
    "const $=i=>document.getElementById(i),estado=$('estado'),conexao=$('conexao'),saida=$('saida'),historico=$('historico');"
    "let pendente=null,ocupado=false,cicloOta=0,primeiroHistorico=true;"
    "const nomesSaude=['Saudável','Recuperando','Atenção','Falha'];"
    "const nomesOta=['Desabilitado','Inicializando','Aguardando rede','Verificando','Atualizado','Aguardando autorização','Baixando','Aplicado','Cancelado','Falha'];"
    "const nomesOtaSat=['Desconhecido','Indisponível','Não suportado','Atualizado','Aguardando autorização','Transferindo','Reiniciando','Concluído','Cancelado','Falha'];"
    "const nomeAlvo=['nenhum','mestre','equipe','visitantes'],nomeNo=['desconhecido','mestre','equipe','visitantes'];"
    "const capacidades=[[1,'Ping'],[2,'Versão'],[4,'Saúde'],[8,'Telemetria'],[16,'UART'],[32,'OTA'],[64,'Wi-Fi'],[128,'Controle OTA'],[256,'Terminal'],[512,'Controle operacional']];"
    "function texto(i,v){$(i).textContent=v}function classeMensagem(t,c){estado.textContent=t;estado.className='estado '+c}"
    "function tomCartao(i,tom){$(i).dataset.tom=tom||''}function tomOta(valor,satelite){valor=Number(valor);if(valor===9)return'erro';if(valor===8)return'alerta';if(satelite&&[3,7].includes(valor))return'sucesso';if(!satelite&&[4,7].includes(valor))return'sucesso';return valor?'alerta':''}function marcarAlvo(i,valor,satelite){$(i).className='alvo '+({sucesso:'sucesso',erro:'erro',alerta:'processando'}[tomOta(valor,satelite)]||'')}"
    "function atualizarBotoes(){document.querySelectorAll('button').forEach(b=>b.disabled=ocupado)}"
    "function bloquear(v){ocupado=v;atualizarBotoes()}function versao(a,d){return a||d||'—'}function percentual(v){return Math.max(0,Math.min(100,Number(v)||0))}"
    "function formatarTempo(ms){ms=Number(ms)||0;if(ms<60000)return Math.round(ms/1000)+' s';if(ms<3600000)return(ms/60000).toFixed(1)+' min';return(ms/3600000).toFixed(1)+' h'}"
    "function listaCapacidades(m){m=Number(m)||0;let n=capacidades.filter(c=>(m&c[0])!==0).map(c=>c[1]);return n.length?n.join(', '):'Nenhuma capacidade reconhecida'}"
    "function qualidadeRssi(r){r=Number(r);if(r>=-50)return'Excelente';if(r>=-60)return'Muito bom';if(r>=-70)return'Bom';if(r>=-80)return'Fraco';return'Muito fraco'}"
    "function registrar(d,ok){if(primeiroHistorico){historico.innerHTML='';primeiroHistorico=false}let li=document.createElement('li'),hora=document.createElement('span'),descricao=document.createElement('span'),meta=document.createElement('small');"
    "hora.textContent=new Date().toLocaleTimeString();descricao.className=ok?'sucesso':'erro';descricao.textContent=(d.consulta||d.acao||'comando')+' · '+(ok?'confirmado':(d.erro||'falhou'));meta.textContent='#'+(d.solicitacao||0)+' · '+(d.duracao_ms||0)+' ms';li.append(hora,descricao,meta);historico.prepend(li);while(historico.children.length>12)historico.lastChild.remove()}"
    "function atualizarMeta(d){texto('metaResposta','Comando '+(d.comando||'—')+' · solicitação #'+(d.solicitacao||0)+' · '+(d.tentativas||0)+' tentativa(s) · '+(d.duracao_ms||0)+' ms');saida.textContent=JSON.stringify(d,null,2)}"
    "function selecionar(c){document.querySelectorAll('[data-consulta]').forEach(b=>b.classList.toggle('ativo',b.dataset.consulta===c))}"
    "function criarCartao(item){let a=document.createElement('article'),r=document.createElement('div'),v=document.createElement('div'),d=document.createElement('div');a.className='cartao'+(item.largo?' largo':'');r.className='rotulo';v.className='valor';d.className='detalhe';r.textContent=item.rotulo;v.textContent=item.valor;d.textContent=item.detalhe||'';a.append(r,v,d);if(item.progresso!==undefined){let b=document.createElement('div'),s=document.createElement('span');b.className='barra';s.style.width=percentual(item.progresso)+'%';b.append(s);a.append(b)}return a}"
    "function exibirConsulta(titulo,descricao,itens,d,semRolagem){texto('tituloConsulta',titulo);texto('descricaoConsulta',descricao);let grade=$('detalhesConsulta');grade.replaceChildren();itens.forEach(i=>grade.append(criarCartao(i)));$('resultadoGeral').hidden=true;$('resultadoConsulta').hidden=false;selecionar(d.consulta);atualizarMeta(d);if(!semRolagem)window.scrollTo({top:0,behavior:'smooth'})}"
    "function versoesAlvo(o){if(!o)return'Informação indisponível';return versao(o.versao_atual,'desconhecida')+(o.versao_disponivel?' → '+o.versao_disponivel:' · sem atualização')}"
    "function modeloConsulta(d){let hex=v=>'0x'+(Number(v)||0).toString(16).toUpperCase();"
    "if(d.consulta==='ping')return['Comunicação com o mestre','Resultado exclusivo do teste de enlace UART',[{rotulo:'Tempo de resposta',valor:d.rtt_ms+' ms',detalhe:d.tentativas+' tentativa(s)'},{rotulo:'Tempo ativo do mestre',valor:formatarTempo(d.tempo_ativo_ms),detalhe:d.tempo_ativo_ms+' ms desde a inicialização'},{rotulo:'Solicitação',valor:'#'+d.solicitacao,detalhe:'Resposta correlacionada e validada'}]];"
    "if(d.consulta==='versao')return['Versão do mestre','Identificação do firmware em execução',[{rotulo:'Firmware',valor:d.firmware,detalhe:'Versão informada pelo mestre'},{rotulo:'Nó do protocolo',valor:nomeNo[d.no]||('nó '+d.no),detalhe:'Identificador '+d.no},{rotulo:'Capacidades',valor:hex(d.capacidades),detalhe:listaCapacidades(d.capacidades),largo:true}]];"
    "if(d.consulta==='capacidades')return['Capacidades do mestre','Funções anunciadas pelo protocolo de comandos',[{rotulo:'Máscara recebida',valor:hex(d.capacidades),detalhe:'Valor anunciado pelo mestre'},{rotulo:'Recursos reconhecidos',valor:listaCapacidades(d.capacidades),detalhe:'Novos bits continuam compatíveis com o mesmo quadro',largo:true}]];"
    "if(d.consulta==='saude')return['Saúde do mestre','Estado atual do sistema e indicadores acumulados',[{rotulo:'Estado',valor:nomesSaude[d.estado]||('Estado '+d.estado),detalhe:'Classificação calculada pelo serviço de saúde'},{rotulo:'Causas ativas',valor:hex(d.causas_ativas),detalhe:d.causas_ativas?'Existem causas ativas':'Nenhuma causa ativa'},{rotulo:'Memória livre',valor:(d.heap_livre/1024).toFixed(1)+' KiB',detalhe:'Heap disponível no momento'},{rotulo:'Erros históricos',valor:d.erros_historicos,detalhe:'Ocorrências acumuladas'},{rotulo:'Tempo ativo',valor:formatarTempo(d.tempo_ativo_ms),detalhe:d.tempo_ativo_ms+' ms'}]];"
    "if(d.consulta==='telemetria')return['Telemetria no mestre','Última amostra mantida pelo serviço de telemetria',[{rotulo:'Velocidade',valor:d.velocidade_kmh.toFixed(1)+' km/h',detalhe:'Valor processado pelo mestre'},{rotulo:'Carga da bateria',valor:d.carga_percentual.toFixed(1)+'%',detalhe:'Estimativa recebida'},{rotulo:'ADC bruto',valor:d.adc,detalhe:'Leitura sem conversão'},{rotulo:'Sequência',valor:'#'+d.sequencia,detalhe:'Tempo do mestre: '+d.tempo_mestre_ms+' ms'}]];"
    "if(d.consulta==='uart')return['UART entre equipe e mestre','Contadores do canal do satélite da equipe',[{rotulo:'Envios concluídos',valor:d.envios,detalhe:'Quadros transmitidos pelo mestre'},{rotulo:'Recepções',valor:d.recepcoes,detalhe:'Quadros recebidos pelo mestre'},{rotulo:'Erros',valor:d.erros,detalhe:d.erros?'Requer atenção':'Nenhum erro acumulado'},{rotulo:'Descartes',valor:d.descartes,detalhe:d.descartes?'Mensagens descartadas':'Nenhum descarte acumulado'}]];"
    "if(d.consulta==='wifi')return['Wi-Fi do mestre','Estado atual do rádio e da conexão externa',[{rotulo:'Estado do rádio',valor:d.conectado?'Conectado':(d.radio_ativo?'Ativo, sem conexão':'Em repouso'),detalhe:d.conectado?'Sessão Wi-Fi estabelecida':'Nenhuma rede conectada'},{rotulo:'Rede',valor:d.rede||'sem rede',detalhe:'SSID informado pelo mestre'},{rotulo:'Sinal',valor:d.conectado?d.rssi_dbm+' dBm':'—',detalhe:d.conectado?qualidadeRssi(d.rssi_dbm):'RSSI indisponível'},{rotulo:'Canal',valor:d.canal||'—',detalhe:'Canal Wi-Fi atual'}]];"
    "if(d.consulta==='configuracao'){let ints=d.intervalos_relatorios_ms||[];return['Configuração operacional','Mesmos ajustes e estados disponíveis no terminal serial',[{rotulo:'Relatórios',valor:d.relatorios_pausados?'Pausados':'Ativos',detalhe:'Telemetria '+(ints[0]||0)+' · UART '+(ints[1]||0)+' · sistema '+(ints[2]||0)+' · OTA '+(ints[3]||0)+' ms',largo:true},{rotulo:'Verificação OTA',valor:d.intervalo_ota_minutos+' min',detalhe:'Telemetria durante OTA: '+d.intervalo_telemetria_ota_ms+' ms'},{rotulo:'Cartão SD',valor:d.cartao_disponivel?'Disponível':'Indisponível',detalhe:d.amostras_sd+' amostras · '+d.arquivos_pendentes+' pendente(s) · '+d.arquivos_enviados+' enviado(s)'},{rotulo:'Redes secundárias',valor:d.quantidade_redes_wifi,detalhe:d.wifi_automatico?'Conexão automática':'Autorização manual'},{rotulo:'Política Wi-Fi',valor:d.tentativas_wifi+' tentativa(s)',detalhe:d.tempo_tentativa_wifi_ms+' ms/tentativa · intervalo '+d.intervalo_tentativas_wifi_ms+' ms · limite '+d.tempo_limite_wifi_ms+' ms',largo:true}]];}"
    "if(d.consulta&&d.consulta.startsWith('satelite_')){let nome=d.alvo===2?'Satélite da equipe':'Satélite de visitantes';if(d.tipo===1)return[nome+' · ping','Consulta encaminhada pelo mestre ao enlace correspondente',[{rotulo:'Tempo de resposta',valor:d.rtt_ms+' ms',detalhe:'Medição feita pelo mestre'},{rotulo:'Tempo ativo',valor:formatarTempo(d.tempo_ativo_ms),detalhe:d.tempo_ativo_ms+' ms'}]];return[nome+' · versão','Identificação consultada diretamente pelo mestre',[{rotulo:'Firmware',valor:d.firmware||'—',detalhe:'Versão informada pelo satélite'},{rotulo:'Capacidades',valor:hex(d.capacidades),detalhe:listaCapacidades(d.capacidades),largo:true}]];}"
    "if(d.consulta==='ota'){let detalhado=d.mestre&&d.equipe&&d.visitantes,m=detalhado?d.mestre:{estado:d.estado,progresso_percentual:d.progresso_percentual,versao_atual:d.versao_atual,versao_disponivel:d.versao_disponivel},e=detalhado?d.equipe:null,v=detalhado?d.visitantes:null;let itens=[{rotulo:'Estado geral',valor:nomesOta[d.estado]||('Estado '+d.estado),detalhe:'Alvo ativo: '+(nomeAlvo[d.alvo]||d.alvo)+' · '+(d.verificacoes||0)+' verificação(ões) · '+(d.falhas||0)+' falha(s)',largo:true},{rotulo:'Mestre',valor:nomesOta[m.estado]||('Estado '+m.estado),detalhe:versoesAlvo(m),progresso:m.progresso_percentual}];if(e)itens.push({rotulo:'Satélite da equipe',valor:nomesOtaSat[e.estado]||('Estado '+e.estado),detalhe:versoesAlvo(e),progresso:e.progresso_percentual});if(v)itens.push({rotulo:'Satélite de visitantes',valor:nomesOtaSat[v.estado]||('Estado '+v.estado),detalhe:versoesAlvo(v),progresso:v.progresso_percentual});return['Atualizações OTA','Estado e versões dos firmwares conhecidos pelo mestre',itens]}return null}"
    "function apresentarConsulta(d,semRolagem){let m=modeloConsulta(d);if(m)exibirConsulta(m[0],m[1],m[2],d,semRolagem)}"
    "function apresentarErro(c,d){exibirConsulta('Falha na consulta','O mestre não forneceu os dados solicitados',[{rotulo:'Consulta',valor:c,detalhe:'Comando solicitado'},{rotulo:'Motivo',valor:d.erro||'Falha desconhecida',detalhe:(d.tentativas||0)+' tentativa(s) · '+(d.duracao_ms||0)+' ms',largo:true}],d)}"
    "function aplicarOta(d){let detalhado=d.mestre&&d.equipe&&d.visitantes,m=detalhado?d.mestre:{estado:d.estado,progresso_percentual:d.progresso_percentual,versao_atual:d.versao_atual,versao_disponivel:d.versao_disponivel};"
    "let e=detalhado?d.equipe:null,v=detalhado?d.visitantes:null,ativo=d.alvo||0,progresso=ativo===2&&e?e.progresso_percentual:ativo===3&&v?v.progresso_percentual:(m.progresso_percentual||0);"
    "texto('otaValor',nomesOta[d.estado]||('Estado '+d.estado));texto('otaDetalhe','Alvo ativo: '+(nomeAlvo[ativo]||ativo)+' · '+(d.falhas||0)+' falha(s) · '+(d.verificacoes||0)+' verificação(ões)');$('otaBarra').style.width=percentual(progresso)+'%';tomCartao('cartaoOta',tomOta(d.estado,false));"
    "texto('otaMestre',nomesOta[m.estado]||('Estado '+m.estado));texto('otaMestreVersao',versoesAlvo(m));"
    "texto('otaEquipe',e?(nomesOtaSat[e.estado]||('Estado '+e.estado)):'formato legado');texto('otaEquipeVersao',e?versoesAlvo(e):'—');"
    "texto('otaVisitantes',v?(nomesOtaSat[v.estado]||('Estado '+v.estado)):'formato legado');texto('otaVisitantesVersao',v?versoesAlvo(v):'—');marcarAlvo('alvoMestre',m.estado,false);marcarAlvo('alvoEquipe',e?e.estado:0,true);marcarAlvo('alvoVisitantes',v?v.estado:0,true)}"
    "function aplicar(d){if(!d||!d.ok)return;if(d.consulta==='ping'){texto('linkValor',d.rtt_ms+' ms');texto('linkDetalhe','Resposta em '+d.tentativas+' tentativa(s) · mestre ativo há '+formatarTempo(d.tempo_ativo_ms));conexao.textContent='Mestre respondendo';conexao.className='selo sucesso';tomCartao('cartaoLink','sucesso')}"
    "else if(d.consulta==='versao'){texto('versaoValor',d.firmware);texto('versaoDetalhe','Nó '+(nomeNo[d.no]||d.no)+' · '+listaCapacidades(d.capacidades));tomCartao('cartaoVersao','sucesso')}"
    "else if(d.consulta==='capacidades'){texto('versaoDetalhe','Capacidades 0x'+Number(d.capacidades).toString(16).toUpperCase())}"
    "else if(d.consulta==='saude'){texto('saudeValor',nomesSaude[d.estado]||('Estado '+d.estado));texto('saudeDetalhe','Causas 0x'+Number(d.causas_ativas).toString(16).toUpperCase()+' · heap '+(d.heap_livre/1024).toFixed(1)+' KiB · erros '+d.erros_historicos);tomCartao('cartaoSaude',d.estado===0?'sucesso':d.estado>=3?'erro':'alerta')}"
    "else if(d.consulta==='wifi'){texto('wifiValor',d.conectado?'Conectado':(d.radio_ativo?'Rádio ativo':'Em repouso'));texto('wifiDetalhe',(d.rede||'sem rede')+' · '+(d.conectado?d.rssi_dbm+' dBm':'sem RSSI')+' · canal '+d.canal);tomCartao('cartaoWifi',d.conectado?'sucesso':d.radio_ativo?'alerta':'')}"
    "else if(d.consulta==='configuracao'){let ints=d.intervalos_relatorios_ms||[];$('intervaloRelatorio').value=String(ints[Number($('grupoRelatorio').value)]??1000);$('intervaloOta').value=String(d.intervalo_ota_minutos);$('intervaloTelemetriaOta').value=String(d.intervalo_telemetria_ota_ms);$('wifiAutomatico').value=d.wifi_automatico?'1':'0';$('tentativasWifi').value=d.tentativas_wifi;$('tempoTentativaWifi').value=d.tempo_tentativa_wifi_ms;$('intervaloTentativasWifi').value=d.intervalo_tentativas_wifi_ms;$('limiteSessaoWifi').value=d.tempo_limite_wifi_ms;texto('resumoWifiConfiguracao',d.quantidade_redes_wifi+' rede(s) secundária(s) · '+(d.wifi_automatico?'conexão automática':'autorização manual'));carregarRedes(d.quantidade_redes_wifi)}"
    "else if(d.consulta==='ota')aplicarOta(d)}"
    "async function carregarRedes(quantidade){let seletor=$('redeWifiSalva'),valor=seletor.value;seletor.replaceChildren();if(!quantidade){let o=document.createElement('option');o.value='';o.textContent='Nenhuma rede salva';seletor.append(o);return}for(let i=1;i<=quantidade;i++){try{let r=await fetch('/api/mestre?consulta=rede_wifi_salva&indice='+i,{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)continue;let o=document.createElement('option');o.value=String(i);o.textContent=i+' · '+d.ssid;seletor.append(o)}catch(_){}}if(valor&&[...seletor.options].some(o=>o.value===valor))seletor.value=valor}"
    "async function executar(c,metodo,opt){opt=opt||{};if(ocupado&&!opt.interno)return null;if(!opt.silencioso){pendente=null;$('confirmacao').hidden=true;bloquear(true);classeMensagem('Enviando '+c+' e aguardando a confirmação pela UART...','processando')}"
    "let controlador=new AbortController(),demorado=['wifi_conectar_preparada','wifi_conectar_salva','wifi_alterar_principal'].includes(c),limite=setTimeout(()=>controlador.abort(),demorado?200000:16000);try{let url='/api/mestre?consulta='+encodeURIComponent(c)+(opt.indice?'&indice='+encodeURIComponent(opt.indice):''),opcoes={method:metodo||'GET',cache:'no-store',signal:controlador.signal};if((metodo||'GET')==='POST'){opcoes.headers={'Content-Type':'text/plain; charset=utf-8'};opcoes.body=opt.corpo||''}let r=await fetch(url,opcoes);let corpo=await r.text(),d;try{d=JSON.parse(corpo)}catch(_){throw new Error('resposta HTTP inválida')}"
    "aplicar(d);if(!opt.silencioso){registrar(d,r.ok&&d.ok);if((metodo||'GET')==='GET'){if(r.ok&&d.ok)apresentarConsulta(d);else apresentarErro(c,d)}classeMensagem(r.ok&&d.ok?'Comando confirmado pelo mestre.':(d.erro||'Comando recusado.'),r.ok&&d.ok?'sucesso':'erro')}"
    "if(!r.ok||!d.ok){if(c==='ping'){conexao.textContent='Mestre sem resposta';conexao.className='selo erro';tomCartao('cartaoLink','erro')}return null}return d}catch(e){let d={ok:false,consulta:c,erro:e.name==='AbortError'?'tempo limite da página excedido':e.message,solicitacao:0,duracao_ms:0};"
    "if(!opt.silencioso){registrar(d,false);if((metodo||'GET')==='GET')apresentarErro(c,d);classeMensagem('Não foi possível concluir o comando.','erro')}if(c==='ping'){conexao.textContent='Mestre sem resposta';conexao.className='selo erro';tomCartao('cartaoLink','erro')}return null}finally{clearTimeout(limite);if(!opt.silencioso)bloquear(false)}}"
    "function abrirGeral(){cicloOta++;selecionar('');$('resultadoConsulta').hidden=true;$('resultadoGeral').hidden=false;window.scrollTo({top:0,behavior:'smooth'})}"
    "async function visaoGeral(){if(ocupado)return;cicloOta++;selecionar('');$('resultadoConsulta').hidden=true;$('resultadoGeral').hidden=false;bloquear(true);classeMensagem('Atualizando a visão geral...','processando');let p=await executar('ping','GET',{silencioso:true,interno:true}),sucessos=p?1:0;if(p){for(const c of ['versao','saude','ota','wifi','configuracao'])if(await executar(c,'GET',{silencioso:true,interno:true}))sucessos++;classeMensagem(sucessos===6?'Visão geral atualizada.':'Visão geral atualizada parcialmente: '+sucessos+' de 6 consultas.',sucessos===6?'sucesso':'processando')}else classeMensagem('O mestre não respondeu ao teste de comunicação.','erro');bloquear(false)}"
    "function prepararSequencia(passos,p){if(ocupado)return;cicloOta++;pendente={passos};texto('pergunta',p);$('confirmacao').hidden=false;$('confirmacao').scrollIntoView({behavior:'smooth',block:'center'})}function preparar(c,p,corpo){prepararSequencia([{c,corpo:corpo||''}],p)}"
    "async function confirmar(){if(!pendente)return;let operacao=pendente;pendente=null;$('confirmacao').hidden=true;let ultimo=null;for(const passo of operacao.passos){ultimo=await executar(passo.c,'POST',{corpo:passo.corpo||''});if(!ultimo)return}let c=operacao.passos[operacao.passos.length-1].c,acoesOta=['verificar_ota','autorizar_todos','autorizar_mestre','autorizar_equipe','autorizar_visitantes','cancelar_ota'];if(acoesOta.includes(c)){let atual=await executar('ota','GET',{silencioso:true});if(atual)apresentarConsulta(atual);let meu=++cicloOta;acompanharOta(meu,c)}else if(c!=='resumo_terminal'){let config=await executar('configuracao','GET',{silencioso:true});if(config)aplicar(config)}}"
    "function cancelar(){pendente=null;$('confirmacao').hidden=true;classeMensagem('Ação cancelada localmente. Nenhum comando foi enviado.','neutro')}"
    "async function acompanharOta(meu,acao){for(let i=0;i<90&&meu===cicloOta;i++){await new Promise(r=>setTimeout(r,2000));let d=await executar('ota','GET',{silencioso:true});if(!d)return;apresentarConsulta(d,true);let final=[4,7,8,9].includes(d.estado)||(acao==='verificar_ota'&&d.estado===5);if(i>0&&final){classeMensagem('Operação OTA: '+(nomesOta[d.estado]||d.estado)+'.',d.estado===9?'erro':'sucesso');return}}}"
    "function falhaFormulario(m){classeMensagem(m,'erro');return false}function valor(i){return $(i).value.trim()}function permissao(){let p=valor('permissaoWifi');if(!p)falhaFormulario('Informe a senha de permissão administrativa.');return p}"
    "function prepararNovaRede(principal){let ssid=valor('ssidWifi'),senha=valor('senhaWifi');if(!ssid||ssid.length>32)return falhaFormulario('Informe um SSID de até 32 caracteres.');if(senha.length<8||senha.length>63)return falhaFormulario('A senha da rede deve ter entre 8 e 63 caracteres.');let passos=[{c:'wifi_preparar',corpo:ssid+'\\n'+senha}];if(principal){let p=permissao();if(!p)return;passos.push({c:'wifi_alterar_principal',corpo:p});prepararSequencia(passos,'Testar, salvar e tornar “'+ssid+'” a rede principal do mestre?')}else{passos.push({c:'wifi_conectar_preparada',corpo:''});if($('salvarWifi').checked)passos.push({c:'wifi_salvar_preparada',corpo:''});prepararSequencia(passos,'Testar a conexão com “'+ssid+'”'+($('salvarWifi').checked?' e salvar a rede?':' sem salvar a rede?'))}}"
    "function prepararRedeSalva(excluir){let i=$('redeWifiSalva').value;if(!i)return falhaFormulario('Selecione uma rede salva.');preparar(excluir?'wifi_excluir_salva':'wifi_conectar_salva',(excluir?'Excluir':'Autorizar conexão com')+' a rede selecionada?',i)}"
    "document.querySelectorAll('[data-consulta]').forEach(b=>b.onclick=()=>{cicloOta++;executar(b.dataset.consulta,'GET')});document.querySelectorAll('[data-acao]').forEach(b=>b.onclick=()=>preparar(b.dataset.acao,b.dataset.pergunta));"
    "$('aplicarIntervaloRelatorio').onclick=()=>preparar('intervalo_relatorio','Alterar o intervalo deste relatório do terminal?',$('grupoRelatorio').value+'\\n'+$('intervaloRelatorio').value);$('aplicarIntervaloOta').onclick=()=>preparar('intervalo_ota','Alterar o intervalo das verificações OTA?',$('intervaloOta').value);$('aplicarIntervaloTelemetriaOta').onclick=()=>preparar('intervalo_telemetria_ota','Alterar o intervalo da telemetria durante OTA?',$('intervaloTelemetriaOta').value);"
    "$('conectarNovaWifi').onclick=()=>prepararNovaRede(false);$('definirPrincipalWifi').onclick=()=>prepararNovaRede(true);$('conectarWifiSalva').onclick=()=>prepararRedeSalva(false);$('excluirWifiSalva').onclick=()=>prepararRedeSalva(true);$('aplicarWifiAutomatico').onclick=()=>{let p=permissao();if(p)preparar('wifi_automatico','Alterar o comportamento das redes secundárias?',$('wifiAutomatico').value+'\\n'+p)};$('aplicarPoliticaWifi').onclick=()=>{let p=permissao();if(p)preparar('wifi_politica','Salvar a nova política de tentativas e tempos do Wi-Fi?',[valor('tentativasWifi'),valor('tempoTentativaWifi'),valor('intervaloTentativasWifi'),valor('limiteSessaoWifi'),p].join('\\n'))};$('restaurarPrincipalWifi').onclick=()=>{let p=permissao();if(p)preparar('wifi_restaurar_principal','Restaurar a rede principal definida no firmware?',p)};"
    "$('atualizar').onclick=visaoGeral;$('voltarGeral').onclick=abrirGeral;$('confirmar').onclick=confirmar;$('voltar').onclick=cancelar;visaoGeral();"
    "</script></body></html>";
